import { EMAIL_RE } from './common.js';

// Customers and suppliers share these fields. The code is generated by the server.
// Returns { values } (database columns) or { error }. partial: only the fields sent (PATCH).
const FIELDS = {
  name: { column: 'name', label: 'Name', max: 150, required: true },
  contactName: { column: 'contact_name', label: 'Contact person', max: 100 },
  email: { column: 'email', label: 'Email', max: 255, email: true },
  phone: { column: 'phone', label: 'Phone', max: 30, phone: true },
  city: { column: 'city', label: 'City', max: 100 },
  address: { column: 'address', label: 'Address', max: 255 },
  notes: { column: 'notes', label: 'Notes', max: 1000 },
};

// Digits with the usual separators: +84 24 3999 0000, (028) 3822-1234.
const PHONE_RE = /^\+?[\d\s().-]{6,30}$/;

export function validateContact(body, { partial = false } = {}) {
  const values = {};
  for (const [field, rule] of Object.entries(FIELDS)) {
    if (partial && body[field] === undefined) continue;
    const text = String(body[field] ?? '').trim();
    if (!text) {
      if (rule.required) return { error: `${rule.label} is required` };
      values[rule.column] = null;
      continue;
    }
    if (text.length > rule.max) return { error: `${rule.label} can be at most ${rule.max} characters` };
    if (rule.email && !EMAIL_RE.test(text)) return { error: 'Please enter a valid email' };
    if (rule.phone && !PHONE_RE.test(text)) return { error: 'Phone can only contain digits, spaces and + - ( )' };
    values[rule.column] = rule.email ? text.toLowerCase() : text;
  }
  if (body.isActive !== undefined) {
    if (typeof body.isActive !== 'boolean') return { error: 'isActive must be true or false' };
    values.is_active = body.isActive ? 1 : 0;
  }
  return { values };
}
